from concurrent.futures import (
    ProcessPoolExecutor)

def ist_prim(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def zaehle(bereich):
    von, bis = bereich
    return sum(ist_prim(n)
               for n in range(von, bis))

if __name__ == "__main__":
    teile = [(i, i + 250_000) for i in
             range(0, 1_000_000, 250_000)]
    with ProcessPoolExecutor() as ex:
        erg = list(ex.map(zaehle, teile))
    print(erg)
    print(sum(erg))
